static List<String> findByEmailUnsafe(Connection conn, String email) throws SQLException {
  List<String> result = new ArrayList<>();
  try (Statement s = conn.createStatement(); ResultSet rs = s.executeQuery("SELECT * FROM users WHERE email = '" + email + "'")) {
    while (rs.next()) result.add(rs.getString("name"));
  }
  return result;
}
findByEmailUnsafe(conn, "jan@example.com");

static List<String> findByEmailSafe(Connection conn, String email) throws SQLException {
  List<String> result = new ArrayList<>();
  try (PreparedStatement ps = conn.prepareStatement("SELECT * FROM users WHERE email = ?")) {
    ps.setString(1, email);
    try (ResultSet rs = ps.executeQuery()) { while (rs.next()) result.add(rs.getString("name")); }
  }
  return result;
}
findByEmailSafe(conn, "cokolwiek' OR '1'='1").size(); // 0

