static boolean loginUnsafe(Connection conn, String username, String password) throws SQLException {
  String sql = "SELECT * FROM users WHERE username='" + username + "' AND password='" + password + "'";
  try (Statement s = conn.createStatement(); ResultSet rs = s.executeQuery(sql)) { return rs.next(); }
}
loginUnsafe(conn, "admin' --", "cokolwiek"); // true - zalogowano bez znajomosci hasla!

static boolean loginSafe(Connection conn, String username, String password) throws SQLException {
  try (PreparedStatement ps = conn.prepareStatement("SELECT * FROM users WHERE username=? AND password=?")) {
    ps.setString(1, username); ps.setString(2, password);
    try (ResultSet rs = ps.executeQuery()) { return rs.next(); }
  }
}
loginSafe(conn, "admin' --", "cokolwiek"); // false

List<String> payloads = List.of("' OR '1'='1", "' OR '1'='1' --", "x' UNION SELECT id,password,password,password FROM users --");
for (String p : payloads) {
  int unsafe = findByEmailUnsafe(conn, p).size();
  int safe = findByEmailSafe(conn, p).size();
  System.out.printf("%-40s | unsafe=%d | safe=%d%n", p, unsafe, safe);
}

