static void testPayloads(Connection conn, List<String> payloads) throws SQLException {
  for (String p : payloads) {
    int unsafeCount = findByEmailUnsafe(conn, p).size();
    int safeCount = findByEmailSafe(conn, p).size();
    String verdict = safeCount == 0 ? "BEZPIECZNY" : "PODATNY";
    System.out.printf("%-40s | unsafe=%d | safe=%d | %s%n", p.substring(0, Math.min(40, p.length())), unsafeCount, safeCount, verdict);
  }
}

