static boolean attemptBlacklistFilter(String input) {
  return input.contains("OR") || input.contains("UNION") || input.contains("--");
}
System.out.println(attemptBlacklistFilter("cokolwiek' OR '1'='1")); // true - zablokowane
System.out.println(attemptBlacklistFilter("cokolwiek' oR '1'='1")); // false - OBEJSCIE! (mala litera 'r')

