static Optional<String> findOrderById(Connection conn, int orderId) throws SQLException {
  try (PreparedStatement ps = conn.prepareStatement("SELECT * FROM orders WHERE id = ?")) { // BRAK warunku user_id = ?
    ps.setInt(1, orderId);
    try (ResultSet rs = ps.executeQuery()) { if (rs.next()) return Optional.of(rs.getString(1)); return Optional.empty(); }
  }
}
