static void runInjectionRegressionTests(Connection conn) throws SQLException {
  List<String> payloads = List.of("' OR '1'='1", "' OR '1'='1' --", "admin' --", "x' UNION SELECT id,password,password,password FROM users --", "1 OR 1=1");
  int passed = 0;
  for (String p : payloads) {
    boolean pass = findByEmailSafe(conn, p).isEmpty();
    System.out.println(p + " -> " + (pass ? "PASS" : "FAIL"));
    if (pass) passed++;
  }
  System.out.println(passed + "/" + payloads.size() + " testow zaliczonych");
}

