class SecurityAudit {
  void runFullAudit(Connection conn) throws SQLException {
    List<String> payloads = List.of("' OR '1'='1", "admin' --", "x' UNION SELECT id,password,password,password FROM users --");
    for (String p : payloads) {
      System.out.println("findByEmailSafe: " + findByEmailSafe(conn, p).size());
      System.out.println("findByNameSafe: " + findByNameSafe(conn, p).size());
      System.out.println("loginSafe: " + loginSafe(conn, p, "x"));
    }
    System.out.println("findByEmailUnsafe: PODATNA - DO NAPRAWY (" + findByEmailUnsafe(conn, payloads.get(0)).size() + " wierszy wyciekly)");
  }
}
